mapper.insert:
insert into gamegroupmemberdetail( USERUNIQUE, USERID, STUDENTNO, STUDENTNAME, TITLE, CONTRIBUTION
                                 , GROUPNAME)
values (#{userUnique}, #{userId}, #{studentNo}, #{studentName}, #{title}, #{contribution}, #{groupName});

mapper.select:
SELECT G.GROUPNAME,G.GROUPCREATERID, G.USERNUMBERS, G.YEARS,
       G.PERIODSOFONEYEAR, G.CURRENTPERIOD FROM HIS_GAMEGROUP G
where teacherid = #{adminID}

select
    GROUPNAME,GROUPCREATERID,TEACHERID,USERNUMBERS,YEARS,PERIODSOFONEYEAR,CURRENTPERIOD,AUTOPERIODFRESH,AUTOYEARFRESH,ENABLEAUTOPERIODFRESH,ENABLEAUTOYEARFRESH,EXCELLENT,GOOD,MEAN,PASSED,FAILED
from GAMEGROUP where GROUPNAME=#{groupName}

mapper.update:
update
    GAMEGROUP set currentPeriod=#{currentPeriod} where
    groupName=#{groupName}

update gamegroup

    MAXSCORE = #{maxScore},
    MINSCORE = #{minScore}

where GROUPNAME = #{groupName};

mapper.select:
SELECT *
FROM gamegroup
WHERE GROUPNAME = #{gameName};

select DISTINCT approveduser.USERNAME, g.years , m.userUnique, m.groupName, m.currentperiod, m.status, g.periodsofoneyear
from (gamegroupmember m, gamegroup g, adstatusofuser a ,approveduser)
where
    approveduser.USERID = m.USERID
  and g.groupname = m.groupname
  and m.groupName = #{groupName}

select *
from gamegroupmemberdetail
where USERUNIQUE = #{userUnique}
  and STUDENTNO = #{studentNo};

select USERUNIQUE
from gamegroupmember
where GROUPNAME = #{groupName}
  and USERID = #{userId};
